#include "kernel_base_check.h"

namespace AscendC {
namespace check {
class TikcppDataCopyCheck : public TikcppBaseCheck {
public:
    TikcppDataCopyCheck(const std::string& name, DataCopyApiParams& param) : TikcppBaseCheck(name), param_(param) {}
    ~TikcppDataCopyCheck() override = default;
    bool CheckAllHighLevel();
    bool CheckAddrAlign();

private:
    bool CheckDataCopyAlign(uint64_t addr, uint8_t pos, bool isSrc);
    DataCopyApiParams& param_;
};
