namespace AscendC {
namespace check {
bool TikcppDataCopyPadCheck::CheckPadParamters()
{
    static constexpr uint32_t dataCopyPadPaddingSizeLimit = 32; // pad element * sizeof(dtype) <= 32
    uint64_t paddingLimit = dataCopyPadPaddingSizeLimit / param_.srcDtypeBytes;
    if (param_.leftPadding > paddingLimit) {
        CHECK_LOG_ERROR(
            "Failed to check leftPadding value in DataCopyPad, its valid range is 0 ~ %lu, current value "
            "is %u.",
            paddingLimit, param_.leftPadding);
        return false;
    }
    if (param_.rightPadding > paddingLimit) {
        CHECK_LOG_ERROR(
            "Failed to check rightPadding value in DataCopyPad, its valid range is 0 ~ %lu, current value "
            "is %u.",
            paddingLimit, param_.rightPadding);
        return false;
    }

    if (param_.isPad && param_.srcDtypeBytes == B64_BYTE_SIZE && param_.paddingValue != 0) {
        CHECK_LOG_ERROR(
            "Failed to check paddingValue value in DataCopyPad when dtype is B64, it must be 0, current "
            "value is %s.",
            std::to_string(param_.paddingValue).c_str());
        return false;
    }
    return true;
}

bool TikcppDataCopyPadCheck::CheckAllHighLevel()
{
    ASCENDC_CHECK(CheckPadParamters());
    return true;
}
} // namespace check
} // namespace AscendC

